using System.Text.Json;
using Biotech.Net.Chemistry;

namespace Biotech.Net.Chemistry.Tests;

/// <summary>
/// Data-driven comparison with values generated by RDKit 2026.09.1 (Data/rdkit_reference.json, produced by
/// Data/rdkit_reference_gen.py) for ~45 molecules: descriptors, aromaticity, fingerprints and scaffolds.
/// </summary>
public class RdkitReferenceTests
{
    private static readonly Lazy<JsonDocument> Doc = new(() =>
        JsonDocument.Parse(File.ReadAllText(Path.Combine(AppContext.BaseDirectory, "Data", "rdkit_reference.json"))));

    public static TheoryData<string> Names()
    {
        var d = new TheoryData<string>();
        foreach (var p in Doc.Value.RootElement.GetProperty("mols").EnumerateObject()) d.Add(p.Name);
        return d;
    }

    private static (Molecule Mol, JsonElement Ref) Load(string name)
    {
        var r = Doc.Value.RootElement.GetProperty("mols").GetProperty(name);
        return (Molecule.FromSmiles(r.GetProperty("smiles").GetString()!), r);
    }

    private static HashSet<long> Ints(JsonElement e) => e.EnumerateArray().Select(x => x.GetInt64()).ToHashSet();

    private static Dictionary<long, int> CountMap(JsonElement e) => e.EnumerateObject().ToDictionary(p => long.Parse(p.Name), p => p.Value.GetInt32());

    [Theory]
    [MemberData(nameof(Names))]
    public void Descriptors_match_rdkit(string name)
    {
        var (m, r) = Load(name);
        Assert.Equal(r.GetProperty("logp").GetDouble(), Crippen.LogP(m), 3);
        Assert.Equal(r.GetProperty("mr").GetDouble(), Crippen.MolarRefractivity(m), 3);
        Assert.Equal(r.GetProperty("tpsa").GetDouble(), Tpsa.Compute(m), 2);
        Assert.Equal(r.GetProperty("mw").GetDouble(), MolecularDescriptors.MolecularWeight(m), 2);
        Assert.Equal(r.GetProperty("exact").GetDouble(), MolecularDescriptors.ExactMass(m), 3);
        Assert.Equal(r.GetProperty("formula").GetString(), MolecularDescriptors.Formula(m));
        Assert.Equal(r.GetProperty("hbd").GetInt32(), MolecularDescriptors.HBondDonors(m));
        Assert.Equal(r.GetProperty("hba").GetInt32(), MolecularDescriptors.HBondAcceptors(m));
        Assert.Equal(r.GetProperty("nhoh").GetInt32(), MolecularDescriptors.LipinskiDonors(m));
        Assert.Equal(r.GetProperty("no").GetInt32(), MolecularDescriptors.LipinskiAcceptors(m));
        Assert.Equal(r.GetProperty("rotb").GetInt32(), MolecularDescriptors.RotatableBonds(m));
        Assert.Equal(r.GetProperty("arom").GetInt32(), MolecularDescriptors.AromaticRingCount(m));
        Assert.Equal(r.GetProperty("fsp3").GetDouble(), MolecularDescriptors.FractionCsp3(m), 3);
        Assert.Equal(r.GetProperty("qed").GetDouble(), Qed.Compute(m), 3);
        if (name != "adamantane") // RDKit counts symmetrized SSSR rings (4); the SSSR has 3
            Assert.Equal(r.GetProperty("rings").GetInt32(), MolecularDescriptors.RingCount(m));
    }

    [Theory]
    [MemberData(nameof(Names))]
    public void Aromatic_atoms_match_rdkit(string name)
    {
        var (m, r) = Load(name);
        var ours = Enumerable.Range(0, m.AtomCount).Where(i => m.Atoms[i].IsAromatic).Select(i => (long)i).ToHashSet();
        Assert.Equal(Ints(r.GetProperty("aromatic_atoms")), ours);
    }

    [Theory]
    [MemberData(nameof(Names))]
    public void Morgan_ecfp_and_fcfp_bits_match_rdkit(string name)
    {
        var (m, r) = Load(name);
        Assert.Equal(Ints(r.GetProperty("morgan2")), MorganFingerprint.Compute(m, 2, 2048).OnBits().Select(x => (long)x).ToHashSet());
        Assert.Equal(Ints(r.GetProperty("fcfp2")), MorganFingerprint.Compute(m, 2, 2048, useFeatures: true).OnBits().Select(x => (long)x).ToHashSet());
        var counts = MorganFingerprint.ComputeCounts(m).Counts.ToDictionary(k => k.Key, k => k.Value);
        Assert.Equal(CountMap(r.GetProperty("morgan_counts")), counts);
    }

    [Theory]
    [MemberData(nameof(Names))]
    public void Maccs_atompair_and_torsion_match_rdkit(string name)
    {
        var (m, r) = Load(name);
        Assert.Equal(Ints(r.GetProperty("maccs")), MaccsKeys.Compute(m).OnBits().Select(x => (long)x).ToHashSet());
        Assert.Equal(CountMap(r.GetProperty("ap")), AtomPairFingerprint.Compute(m).Counts.ToDictionary(k => k.Key, k => k.Value));
        Assert.Equal(CountMap(r.GetProperty("tt")), TopologicalTorsionFingerprint.Compute(m).Counts.ToDictionary(k => k.Key, k => k.Value));
    }

    [Theory]
    [MemberData(nameof(Names))]
    public void Murcko_scaffold_matches_rdkit(string name)
    {
        var (m, r) = Load(name);
        string rd = r.GetProperty("murcko").GetString()!;
        string expected = rd.Length == 0 ? "" : Molecule.FromSmiles(rd).ToSmiles(includeStereo: false);
        Assert.Equal(expected, MurckoScaffold.GetScaffoldSmiles(m));
    }

    [Theory]
    [MemberData(nameof(Names))]
    public void Canonical_smiles_is_invariant_to_input_order(string name)
    {
        var (m, r) = Load(name);
        string canon = m.ToSmiles();
        Assert.Equal(canon, Molecule.FromSmiles(canon).ToSmiles());
        // RDKit's canonical SMILES is a different atom ordering of the same molecule
        Assert.Equal(canon, Molecule.FromSmiles(r.GetProperty("canon").GetString()!).ToSmiles());
    }

    [Fact]
    public void Tanimoto_values_match_rdkit()
    {
        foreach (var p in Doc.Value.RootElement.GetProperty("tanimoto").EnumerateObject())
        {
            var s = p.Value.GetProperty("smiles").EnumerateArray().Select(x => Molecule.FromSmiles(x.GetString()!)).ToArray();
            Assert.Equal(p.Value.GetProperty("ecfp4").GetDouble(), Similarity.Tanimoto(MorganFingerprint.Ecfp4(s[0]), MorganFingerprint.Ecfp4(s[1])), 9);
            Assert.Equal(p.Value.GetProperty("maccs").GetDouble(), Similarity.Tanimoto(MaccsKeys.Compute(s[0]), MaccsKeys.Compute(s[1])), 9);
        }
    }
}
